// ============================================================
//  Adrenal Fatigue & Stress Assessment — Score Calculator
//  Based on the Q008 Make.com blueprint.
//
//  5 questions, each with a weighted frequency scale:
//    Never        = 0
//    Occasionally = 2
//    Frequently   = 5
//    Constantly   = 8
//  Max score: 5 × 8 = 40
//
//  Scoring tiers — mirroring Q008 blueprint switch exactly:
//    score ≤ 9        → Result 1 (Minimal adrenal load)
//    score 10–22      → Result 2 (Mild to moderate)
//    score 23–39      → Result 3 (Moderate to severe)
//    score 40         → Result 4 (Severe / adrenal exhaustion)
// ============================================================

const data = $input.first().json.body || $input.first().json;

const scoreMap = {
  'never':        0,
  'occasionally': 2,
  'frequently':   5,
  'constantly':   8
};

const fields = [
  'q1_fatigue',
  'q2_irritability',
  'q3_anxious',
  'q4_sleep',
  'q5_energy_crashes'
];

let totalScore = 0;
const scores = {};
const warnings = [];

for (const field of fields) {
  const raw = data[field];
  const key = raw ? String(raw).trim().toLowerCase() : 'never';
  const score = scoreMap[key] !== undefined ? scoreMap[key] : 0;
  scores[field] = { raw, key, score };
  totalScore += score;
  if (!raw) warnings.push(field + ' is missing');
}

// Four-tier result — matching Q008 blueprint switch exactly
let resultNum, resultLabel, resultContent;
if (totalScore <= 9) {
  resultNum = 1;
  resultLabel = 'Minimal Adrenal Load';
  resultContent = 'Your score suggests a low level of adrenal stress at this time. Your cortisol and adrenal function appear to be coping well with your current demands. Maintaining healthy sleep, nutrition, and stress management habits is recommended.';
} else if (totalScore >= 10 && totalScore <= 22) {
  resultNum = 2;
  resultLabel = 'Mild to Moderate Adrenal Stress';
  resultContent = 'You are experiencing some signs of adrenal stress. The early warning signs of adrenal dysfunction are present — particularly fatigue, irritability, anxiety, and disrupted sleep. A targeted adrenal hormone panel and nutritional support can make a significant difference before the condition progresses.';
} else if (totalScore >= 23 && totalScore <= 39) {
  resultNum = 3;
  resultLabel = 'Moderate to Severe Adrenal Fatigue';
  resultContent = 'Your score indicates significant adrenal dysfunction. Persistent exhaustion, emotional dysregulation, anxiety, poor sleep, and afternoon energy crashes are hallmarks of adrenal fatigue. A comprehensive hormonal assessment alongside targeted adrenal support is strongly recommended.';
} else {
  resultNum = 4;
  resultLabel = 'Severe Adrenal Exhaustion';
  resultContent = 'Your score is at the maximum level, indicating severe adrenal exhaustion. Every symptom assessed is occurring constantly. This requires immediate clinical attention. Please reach out to one of our specialists as soon as possible.';
}

return [{ json: {
  patientName:    data.first_name   || '',
  patientEmail:   data.email        || '',
  mailingList:    data.mailing_list || '',
  totalScore,
  resultNum,
  resultLabel,
  resultContent,
  _debug_scores:   scores,
  _debug_warnings: warnings
}}];

const d = $input.first().json;
// Escape only the dynamic name used in the HTML greeting.
function escapePatientName(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}
const greeting = d.patientName ? ('Dear ' + escapePatientName(d.patientName)) : 'Hi there';
const year = new Date().getFullYear();

const introMap = {
  1: `The adrenal glands are small glands that sit on top of your kidneys and produce hormones essential for life — including cortisol (your primary stress hormone), DHEA, and adrenaline. When these glands are healthy and well-supported, your body handles stress efficiently, your energy is stable, and your mood is balanced.<br/><br/>Based on your responses, your adrenal system appears to be coping well right now. This is a good position to be in — and maintaining it requires the same foundations that support all hormonal health: quality sleep, regular physical activity, balanced nutrition, and effective stress management.<br/><br/>We recommend establishing a baseline adrenal hormone panel at least once every few years, particularly as you age, so you have a reference point should symptoms develop in the future.`,
  2: `The adrenal glands regulate your body's response to stress through the production of cortisol and DHEA. When stress is sustained over time — whether physical, emotional, or environmental — the adrenals are pushed harder and begin to show early signs of strain.<br/><br/>Based on your responses, you are experiencing some of the hallmarks of early adrenal stress: fatigue, irritability, anxiety, and disrupted sleep. These symptoms arise because elevated cortisol disrupts the sleep-wake cycle, depletes serotonin and GABA (calming neurotransmitters), and impairs cellular energy production.<br/><br/>At this stage, a targeted adrenal hormone panel, nutritional support, and lifestyle adjustments can prevent the condition from progressing. DHEA levels in particular tend to decline as cortisol demands increase — and restoring DHEA can meaningfully improve energy, mental clarity, and emotional resilience. We recommend speaking to one of our specialists to discuss your options.`,
  3: `Adrenal fatigue is a condition in which prolonged or intense stress has overwhelmed your adrenal glands' ability to maintain normal cortisol output. This leads to a wide range of symptoms that significantly affect your daily functioning — including the persistent exhaustion, anxiety, emotional dysregulation, sleep disruption, and afternoon energy crashes you are experiencing.<br/><br/>The cascade effects of dysregulated cortisol are extensive: it disrupts thyroid function (often misdiagnosed as hypothyroidism), suppresses sex hormone production (reducing testosterone and progesterone), impairs immune function, destabilises blood sugar, and interferes with restorative sleep — creating a self-reinforcing cycle that worsens over time without intervention.<br/><br/>Recovery is absolutely possible, but it requires understanding exactly where your cortisol output stands (a 4-point salivary cortisol profile is the gold standard), combined with targeted hormonal support, adrenal-specific nutrition, and expert guidance. Our specialists are experienced in interpreting adrenal hormone results and creating personalised recovery protocols.`,
  4: `Adrenal exhaustion — sometimes referred to as stage 3 adrenal fatigue — represents the most advanced stage of HPA axis dysregulation. At this point, the adrenal glands have been under severe and sustained demand and cortisol output has become critically depleted. The symptoms you are experiencing across every category are the direct result of this depletion.<br/><br/>The impact of severe adrenal exhaustion extends far beyond fatigue and mood. It suppresses immune function (increasing susceptibility to infection), disrupts thyroid hormone conversion (worsening fatigue and metabolic function), depletes sex hormones (reducing testosterone, progesterone, and oestrogen), impairs memory and concentration, and destabilises blood pressure and blood sugar regulation.<br/><br/>Recovery requires a carefully structured and professionally guided protocol. It is not something to manage alone, and it does take time — but with the right support, it is entirely achievable. Please reach out to our specialists as a matter of priority. They understand the complexity of adrenal exhaustion and can create a comprehensive recovery plan based on your individual hormone test results.`
};

